int I_NDS_is_trusted ( struct sip_msg * msg , char * str1 , char * str2 ) { struct via_body * vb ; str subdomain ; int i ; vb = msg -> via1 ; if ( ! vb ) { LM_ERR ( "ERR:I_NDS_is_trusted: Error VIA1 hdr not found\n" ) ; return 0 ; } subdomain = vb -> host ; LM_DBG ( "DBG:I_NDS_is_trusted: Message comes from<%.*s>\n" , subdomain . len , subdomain . s ) ; i = 0 ; while ( trusted_domains [ i ] . len ) { i ++ ; } return CSCF_RETURN_FALSE ; } 